import numpy as np

class HarmonicSphere:
    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        r = np.linalg.norm(x)
        return r**2 + 0.1 * np.sum(np.abs(x)) * np.exp(-r**2 / 10)

import numpy as np

class UniformPeriodicLattice:
    def __init__(self, dim=5):
        self.dim = dim
        self.frequency = 0.35  # ~7 oscillations in [-5, 5] range

    def f(self, x):
        n = len(x)

        # Primary term: uniform periodic grid across all dimensions
        # Creates identical basin sizes through consistent frequency
        primary_term = sum(np.cos(2 * np.pi * self.frequency * x[i])**2 
                         for i in range(n))

        # Secondary term: cross-dimensional coupling maintaining same frequency
        # Adds complexity while preserving basin size homogeneity
        cross_term = 0.15 * sum(np.cos(2 * np.pi * self.frequency * (x[i] + x[(i+1)%n]))**2 
                              for i in range(n))

        # Tertiary term: rotational coupling for isotropic behavior
        rotational_term = 0.1 * sum(np.cos(2 * np.pi * self.frequency * (x[i] - x[(i+1)%n]))**2 
                                  for i in range(n))

        return primary_term + cross_term + rotational_term

import numpy as np

class HarmonicBeatingLattice:
    def __init__(self, dim=5):
        self.dim = dim
        self.base_freq = 0.5
        self.harmonics = [1, 2, 3, 4]  # Multiple frequency components for beating
        self.coupling_strength = 0.12

    def f(self, x):
        n = len(x)

        # Multi-frequency harmonic interference creates complex periodic structure
        # Each dimension has 4 different frequencies creating beating patterns
        primary_term = sum(
            sum(np.sin(2 * np.pi * self.base_freq * h * x[i])**2 
                for h in self.harmonics)
            for i in range(n)
        )

        # Nonlinear coupling through product in cosine argument
        # Creates diagonal interference patterns different from simple addition
        coupling_term = self.coupling_strength * sum(
            np.cos(2 * np.pi * self.base_freq * (x[i] * x[(i+1) % n]))
            for i in range(n)
        )

        # Rotational coupling for isotropic basin structure
        rotational_term = 0.08 * sum(
            np.cos(2 * np.pi * self.base_freq * (x[i]**2 + x[(i+1) % n]**2))
            for i in range(n)
        )

        # Global minimum at origin where all harmonics align to minimum value
        # Each dimension contributes len(harmonics) to the sum of sin^2 terms
        # sin^2(0) = 0 for all harmonics, cos(0) = 1 for coupling terms
        offset = len(self.harmonics) * n

        return primary_term + coupling_term + rotational_term - offset
